1: import { createPortal } from "react-dom";
2: import type { ReactNode } from "react";
3: import "./OfficialCourseListModal.css";
4: 
5: export type RouteListModalShellProps = {
6:   /** 제목 요소의 id — 각 모달이 다른 값을 쓴다(둘이 같으면 셀렉터가 서로를 집는다) */
7:   titleId: string;
8:   /** 제목 칩에 보이는 짧은 이름(입문 · 퍼블릭 · 내 경로) */
9:   title: string;
10:   /** 대화상자 접근성 이름 — 짧은 칩 대신 온전한 이름(「입문 경로」 등)을 읽힌다 */
11:   dialogLabel: string;
12:   /** 제목 줄 검색 — 값·변경 핸들러는 목록을 거르는 쪽이 소유한다 */
13:   searchValue: string;
14:   onSearchChange: (value: string) => void;
15:   onClose: () => void;
16:   children: ReactNode;
17: };
18: 
19: /**
20:  * 경로 목록 모달의 공용 껍데기 — 오버레이 · 제목 줄 · 스크롤 본문.
21:  *
22:  * 2026-09-16(B단계): 「내 경로」가 공식 코스와 같은 급의 모달을 갖게 되면서
23:  * `OfficialCourseListModal` 이 혼자 들고 있던 껍데기를 여기로 뺐다.
24:  * 스타일은 종전 `oc-modal*` 를 그대로 쓴다 — 두 모달이 같은 옷을 입어야
25:  * 「경로를 고르는 자리」로 읽힌다.
26:  *
27:  * 2026-10-06(Chief): 제목 줄 한 줄에 [제목 칩][검색][X] 를 담는다. 종전에는 제목 줄이
28:  * 제목과 「닫기」만 들고 있었고 검색은 본문 첫 줄을 따로 먹었다(내 경로), 입문·퍼블릭은
29:  * 검색이 아예 없었다. 닫기는 글자 대신 X 로 우상단 구석에 붙여 검색 폭을 최대로 준다.
30:  * 닫기 버튼의 접근성 이름(「닫기」)과 대화상자 이름(「입문 경로」 등)은 그대로 — e2e 계약.
31:  */
32: export function RouteListModalShell(props: RouteListModalShellProps) {
33:   return createPortal(
34:     <div className="oc-modal-overlay" role="presentation" onMouseDown={() => props.onClose()}>
35:       <div
36:         className="oc-modal"
37:         role="dialog"
38:         aria-label={props.dialogLabel}
39:         aria-modal="true"
40:         onMouseDown={(e) => e.stopPropagation()}
41:       >
42:         <div className="oc-modal__head">
43:           <h2 id={props.titleId} className="oc-modal__title">
44:             {props.title}
45:           </h2>
46:           <input
47:             type="search"
48:             className="oc-modal__search"
49:             value={props.searchValue}
50:             placeholder="경로 이름 검색"
51:             aria-label="경로 이름 검색"
52:             onChange={(e) => props.onSearchChange(e.target.value)}
53:           />
54:           <button
55:             type="button"
56:             className="oc-modal__close"
57:             aria-label="닫기"
58:             title="닫기"
59:             onClick={() => props.onClose()}
60:           >
61:             <span aria-hidden="true">✕</span>
62:           </button>
63:         </div>
64:         <div className="oc-modal__body">{props.children}</div>
65:       </div>
66:     </div>,
67:     document.body,
68:   );
69: }

