189:         ) : null}
190:       </>
191:     ) : (
192:       <>
193:         {!props.officialCourseCatalogAvailable ? (
194:           <p className="oc-modal__hint">목록 미연결</p>
195:         ) : props.publishedPublicCoursesLoading ? (
196:           <p className="oc-modal__hint">불러오는 중…</p>
197:         ) : props.publishedPublicCoursesError ? (
198:           <p className="oc-modal__error" role="alert">
199:             목록을 불러오지 못했어요.{" "}
200:             <span className="oc-modal__error-detail">{props.publishedPublicCoursesError}</span>
201:           </p>
202:         ) : props.publishedPublicCourses.length === 0 ? (
203:           <p className="oc-modal__hint">
204:             {!props.signedIn && props.officialCourseCatalogAvailable
205:               ? "로그인 후 목록"
206:               : "퍼블릭 경로 없음"}
207:           </p>
208:         ) : (
209:           <>
210:           {sortBar}
211:           {publicCourses.length === 0 ? <p className="oc-modal__hint">검색 결과가 없습니다.</p> : null}
212:           <ul className="oc-modal__list">
213:             {publicCourses.map((c) => (
214:               <PublicCoursePickRow
215:                 key={c.id}
216:                 course={c}
217:                 selected={props.basicActiveHubCourseId === c.id}
218:                 loadDisabled={loadDisabled}
219:                 activityBadge={formatRouteActivityListBadge(
220:                   props.publicationActivityByPublicationId?.get(c.id) ?? null,
221:                 )}
222:                 onLoad={() => handleLoad(c.id)}
223:               />
224:             ))}
225:           </ul>
226:           </>
227:         )}
228:       </>
229:     );
230: 
231:   return (
232:     <RouteListModalShell
233:       titleId="oc-modal-title"
234:       title={segmentChip(props.segment)}
235:       dialogLabel={segmentTitle(props.segment)}
236:       searchValue={queryText}
237:       onSearchChange={setQueryText}
238:       onClose={props.onClose}
239:     >
240:       {body}
241:     </RouteListModalShell>
242:   );
243: }

