+  overflow-x: hidden;
+  overflow-y: auto;
+}
+
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__error {
+  flex-shrink: 0;
+}
+
+.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__error-detail {
+  overflow-wrap: anywhere;
+}

